before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>

int main(void) {
    FILE *file = fopen("lesson.txt", "w");
    if (file == NULL) { puts("open failed"); return 1; }
    int wrote = fputs("ready", file) != EOF;
    int closed = fclose(file) == 0;
    if (!wrote || !closed) { puts("write failed"); return 1; }
    puts("saved");
    return 0;
}
```

